+    }
+}
+
+#[test]
+fn a_code_that_is_no_od_blade_is_refused_by_name() {
+    let (world, mut history) = bar_world();
+    create(&world, &mut history, "G1", groove());
+    for q in [3u8, 4, 5, 7, 8] {
