+        // A bore wall: the +X family.
+        assert_eq!(fitting(&[Contact::PlusX]), vec![3, 4, 5, 7, 8]);
+        // Facing inward: the face below and the pass's leading -X.
+        assert_eq!(fitting(&[Contact::MinusX, Contact::MinusZ]), vec![2, 6, 7]);
